#!/usr/bin/env node
/**
 * Publishes Orazaka's documentation on this site (/docs).
 *
 *   node scripts/sync-docs.mjs <orazaka-content/docs dir> <docs-manifest.ts>
 *
 * The markdown is generated by `orazaka docs sync` (krizaka/orazaka); what is published is the allow-list of
 * krizaka.com's `lib/docs-manifest.ts` (title, category, order, intro). Never hand-edit `content/docs`: change the
 * Orazaka source, sync, run this again. Fenced diagram blocks (architecture, pipeline, sequence, states) are drawn by
 * krizaka.com's engine from the generated model; here they are dropped, the text around them carries the facts.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const [srcDir, manifestFile] = process.argv.slice(2);
if (!srcDir || !manifestFile) {
  console.error("usage: node scripts/sync-docs.mjs <docs dir> <docs-manifest.ts>");
  process.exit(1);
}

const manifest = parseManifest(fs.readFileSync(manifestFile, "utf8"));
const out = path.join(root, "content", "docs");
fs.rmSync(out, { recursive: true, force: true });
fs.mkdirSync(out, { recursive: true });

const files = Object.fromEntries(fs.readdirSync(srcDir).filter((f) => f.endsWith(".md")).map((f) => [f.slice(0, -3).toLowerCase(), f]));
const index = [];
for (const [slug, meta] of Object.entries(manifest)) {
  const file = files[slug];
  if (!file) {
    console.warn(`skip ${slug}: not in ${srcDir}`);
    continue;
  }
  const body = clean(fs.readFileSync(path.join(srcDir, file), "utf8"));
  fs.writeFileSync(path.join(out, `${slug}.md`), body);
  index.push({ slug, ...meta, file: `${slug}.md` });
}
index.sort((a, b) => a.category.localeCompare(b.category) || a.order - b.order);
fs.writeFileSync(path.join(out, "index.json"), `${JSON.stringify(index, null, 2)}\n`);
process.stdout.write(`${index.length} docs published in content/docs\n`);

function parseManifest(ts) {
  const entries = {};
  const re = /^ {2}(?:"([^"]+)"|(\w+)): \{\s*title: "((?:[^"\\]|\\.)*)",\s*category: "([^"]+)",\s*order: (\d+),\s*audience: "([^"]+)",\s*intro:\s*"((?:[^"\\]|\\.)*)"/gm;
  for (const m of ts.matchAll(re)) {
    entries[m[1] ?? m[2]] = { title: JSON.parse(`"${m[3]}"`), category: m[4], order: Number(m[5]), audience: m[6], intro: JSON.parse(`"${m[7]}"`) };
  }
  return entries;
}

function clean(md) {
  return md
    .replace(/^---\n[\s\S]*?\n---\n/, "")
    .replace(/^```(?:architecture|pipeline|sequence|states)\b[\s\S]*?^```\n?/gm, "")
    .trimStart();
}
